compact/powershell/pi/ollama-embed/vllm-.copy:
# Keep generated configuration files out of version control.
if (-not (Test-Path .gitignore)) { New-Item -ItemType File -Path .gitignore | Out-Null }
Add-Content -Path .gitignore -Value '.chunkhound.json'
Add-Content -Path .gitignore -Value '.mcp.json'
# Configure ChunkHound with Ollama embeddings and vLLM for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
@'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "openai",
    "model": "Qwen/Qwen3-Coder-30B-A3B-Instruct",
    "base_url": "http://localhost:8002/v1"
  }
}
'@ | Set-Content -Path '.chunkhound.json' -Encoding utf8
# Configure Pi to connect to ChunkHound via MCP.
pi install npm:pi-mcp-adapter
if (Test-Path '.mcp.json') {
Write-Host @'
.mcp.json already exists — merge this block into it manually:
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ],
      "directTools": true,
      "lifecycle": "eager",
      "requestTimeoutMs": 1200000
    }
  },
  "settings": {
    "outputGuard": false
  }
}
'@
} else {
@'
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ],
      "directTools": true,
      "lifecycle": "eager",
      "requestTimeoutMs": 1200000
    }
  },
  "settings": {
    "outputGuard": false
  }
}
'@ | Set-Content -Path '.mcp.json' -Encoding utf8
}
# Build ChunkHound's search index for this project.
chunkhound index .

